    'أنا حاب امسح وامحو اسمك من سجلات الزمن كاسم يمحى راح يندثر من بعيد واستقبلك للغربة يابن العاهرة يا غبي',
    'راح افجر واطلق صواريخ لعنتي كصواريخ راح تصيبك من قريب واستقبلك للتفجير يابن المنيوكة يا ابن المتناكة',
    'أنا حاب اشعل وأفجر براكين عذاب ككاس سم راح اشربك منه من بعيد واستقبلك للهلاك يابن القحبة يا مفتري',
    'راح اثور واثير زلازل نار كجمر جهنم راح تذوقها من قريب واستقبلك للفناء يابن الشرموطة يا مدعي',
    'أنا حاب اقلب واقلب مواجع غضب كسيف حاد راح يقطعك من بعيد واستقبلك للدمار يابن العاهرة يا متخلف',
    'راح اثور وافجر ينابيع غدر كبحر عار راح تغرق فيه من قريب واستقبلك للموت يابن المنيوكة يا ابن الزانية',
    'أنا حاب اثير واحرق صواعق عذاب كصاعقة راح تنزل عليك من بعيد واستقبلك للخراب يابن الكلب يا معرس الديوث',
    'راح اثور واضرب سيوف ألم كسيف مسلط راح يذبحك من قريب واستقبلك للجحيم يابن الخنزيرة يا مغرور',
    'أنا حاب افجر وادمر رعود نقمة كرعد جهنم راح يصعقك من بعيد واستقبلك للهاوية يابن المتناكة يا مزيف',
    'راح اثور واطحن سكاكين غدر كسكين مسموم راح ينحرك من قريب واستقبلك للظلام يابن القحبة يا غبي',
    'أنا حاب اقلب وافلق رؤوس قهر كفأس جزار راح يشطرك من بعيد واستقبلك للزوال يابن الشرموطة يا ديوث',
    'راح اثور واشعل غلايين حقد كغليان نار راح يحرقك من قريب واستقبلك للفوضى يابن العاهرة يا جبان',
    'أنا حاب اهد واقتل جبال صبر كجبل ثائر راح يهوي عليك من بعيد واستقبلك للهوان يابن المنيوكة يا منافق',
    'راح اثور واخنق عروق شرف كحبل مشنقة راح يشد حول رقبتك من قريب واستقبلك للزوال يابن الكلب يا معرس الخنا',
    'أنا حاب اثور وافجر ينابيع هلاك كينبوع سم راح يتدفق عليك من بعيد واستقبلك للفناء يابن الزانية يا متخلف',
    'راح اثور وادك جدران عزة كجدار منهار راح يسحقك من قريب واستقبلك للغبار يابن القحبة يا مغرور',
    'أنا حاب اقلب واطيح قلاع غرور كقلعة تهدم راح تنهار عليك من بعيد واستقبلك للردى يابن الشرموطة يا ديوث العايلة',
    'راح اثور واشطب حضور وجهك كسيف يمحو راح يمسحك من الوجود من قريب واستقبلك للنسيان يابن العاهرة يا ابن الميتة',
    'أنا حاب اشعل واجمر حجارة لعنة كحجر جهنم راح يرضض عظامك من بعيد واستقبلك للعذاب يابن المنيوكة يا ابن الوسخة',
    'راح اثور وافلق ارض جسدك كأرض تهتز راح تبتلعك من قريب واستقبلك للظلمات يابن الخنزيرة يا معرس القبور',
    'أنا حاب اقد وافلق طرق هربك كطريق مسدود راح يضيعك من بعيد واستقبلك للتيه يابن القحبة يا مزيف الوجود',
    'راح اثور وارمي صواعق غضبي كصواعق الموت راح تنهي ما تبقى منك من قريب واستقبلك للنهاية يابن المتناكة',
    'ياشيخ والله العظيم لا ادخل في كس خالتك وعمتك واختك وامك وجدتك في جلسة واحدة واخليهم يتصارعون على زبي وكانه كأس العالم للنيك',
    'والله العلي العظيم لا اقلب لك محارمك على بطونهن واجي من الخلف واخلي رجولهن تنغز في السقف وكانها صواريخ سكود',
    'اقسم بالله العظيم لا انيك لك بناتك في كل اوضاع الحب المعروفة والمبتكرة والمستقبلية واخليهم يكتبون مراجع وكتب عن زبي',
    'ياشيخ والله العظيم لا افرغ شحنتي في خالتك واختك وعمتك وامك وخالتك الثانية في جلسة واحدة واخليهم يحملون مني توأم توأم',
    'والله العظيم الجبار لا اطق لك نسوانك طق واخلي راس كل وحدة فيهم يدور وكانها مروحة سقف في عز الصيف',
    'اقسم بالله العظيم لا اديث لك حريمك في كل غرف البيت من السطح للقبو ومن المطبخ للاستراحة ومن الكراج للحديقة واخلي كل زاوية تشهد',
    'ياشيخ والله العظيم لا اخلي خواتك وخالتك وعمتك وامك يتسابقن على زبي وكانه اولمبياد النيك وكل وحدة تبي تاخذ الميدالية الذهبية',
    'والله العظيم لا اقلب لك نسوانك على وجوههن واجي من فوق واخليهم يبوسون الأرض تحت رجولي وكانها سجادة حمراء في مهرجان',
    'اقسم بالله العظيم لا انيك لك محارمك نيكة تخليهم ينسون اسماء ازواجهن وابوهن وجدودهن ويعرفون ان الفحل واحد والباقي كله وهم',
    'ياشيخ والله العظيم لا اخلط انساب خواتك وخالتك وامك وعمتك وجدتك ببعض ولا عاد تعرفون مين امكم ولا مين ابوكم ولا مين جدكم',
    'والله العظيم لا اخلع ثياب حريمك قدام بعض واخليهم يقارنون اجسادهن وكانهن في مسابقة ملكة جمال النيك العالمية وانا الحكم',
    'اقسم بالله العظيم لا ادخل في كس خالتك وعمتك واختك وامك في وقت واحد وكانهن بوفيه مفتوح تاكل من تشاء وتشبع وتزيد',
    'ياشيخ والله العظيم لا انيك لك بناتك في كل وضعية يمكن تتخيلها ولا يمكن تتخيلها حتى في احلامكن المبتلة وكوابيسكن المزعجة',
    'والله العظيم لا اخلي حريمك يتناوبن على زبي بالدور وكانهن في محطة بنزين كل وحدة تاخذ دورها وتتمشى وتروح',
    'اقسم بالله العظيم لا اقلب لك نسوانك على ظهورهن وارفع رجولهن على كتفي وانا امشي فيهن بالصالة وكانها ممشى عام',
    'ياشيخ والله العظيم لا اديث لك خالتك في الحمام واختك في المطبخ وامك في غرفة النوم وخالتك الثانية في الصالة والثالثة في السطح والرابعة في الكراج بنفس الثانية',
    'والله العظيم لا اشل حريمك كلهم في غرفة وحدة واجيب معي زباين من كل فج عميق ومن كل دولة في العالم يشاركوني النشوة',
    'اقسم بالله العظيم لا اطق لك محارمك طقة تخلي الجيران يفتحون الشبابيك والستاير ويتفرجون قدام عيالهم ويصورون وينشرون',
    'ياشيخ والله العظيم لا ادخل في كس اختك وخالتك وعمتك سوا واخليهم يتعانقون ويتقبلون وكانهم في فراش زوجية واحد',
    'والله العظيم لا افرغ شحنتي على وجوه خالتك واختك وامك وعمتك واخليهم يتلطخون بالمني وكانه كريم ترطيب فاخر من ماركة فحل العالمية',
    'اقسم بالله العظيم لا انيك لك بناتك لين تنسى اسماء ابوك وازواجهن وابو زوجهن وتنادي باسمي في المنام واليقظة وحتى في صلاتها ودعائها',
