    'اقسم بالله العظيم لا اديث لك خالتك وعمتك واخواتك وامك وخالتك الثانية وعمتك الثانية في جلسة وحدة ويصرخن يا فحل يلا تعال خلصنا',
    'ياشيخ والله العظيم لا اخلع ملابس حريمك وارصهم على السرير وكانهن في طابور عسكري للفحل كل وحدة تنتظر دورها بفارغ الصبر وتتمنى يجي دورها',
