# متغيرات لحماية التكرار
last_reply_time = {}
REPLY_COOLDOWN = 2.0

def is_repetition_message(text):
    if "٬" in text or "(" in text or ")" in text:
        return True
    if re.search(r"[0-9٠-٩]", text):
        return True
    return False

def convert_number(number):
    number = number.translate(ARABIC_DIGITS)
    number = re.sub(r"[\s~]+", "", number)
    number = re.sub(r"[^0-9]", "", number)
    if not number:
        return None
    try:
        return int(number)
    except ValueError:
        return None

def process_repetition(text):
    pattern = re.compile(
        r"(?P<word>[\u0600-\u06FFA-Za-z_]+)"
        r"\s*"
        r"(?:"
            r"\(\s*"
            r"(?P<num1>[0-9٠-٩]+(?:\s*[~٬]\s*[0-9٠-٩]+)*)"
            r"\s*\)?"
            r"|"
            r"[٬]\s*"
            r"(?P<num2>[0-9٠-٩]+(?:\s*[~٬]\s*[0-9٠-٩]+)*)"
            r"|"
            r"(?P<num3>[0-9٠-٩]+(?:\s*[~٬]\s*[0-9٠-٩]+)*)"
            r"\)?"
        r")"
    )
    def replace_match(match):
        word = match.group("word")
        number_text = match.group("num1") or match.group("num2") or match.group("num3")
        count = convert_number(number_text)
        if count is None:
            return match.group(0)
        count = min(count, 100)
        return " ".join([word] * count)
    return pattern.sub(replace_match, text)

def add_spaces(text):
    text = re.sub(r"\s+", " ", text).strip()
    return text.replace(" ", " ~ ")

async def delete_command_message(event):
    try:
        await event.delete()
    except Exception:
        pass

def get_status_text():
    target_status = "🟢 مفعل" if TARGET_MODE else "🔴 معطل"
    tracking_status = f"👁️ {TRACKING_USERNAME}" if TRACKING_USERNAME else "❌ غير مفعل"
    return f"""
╔══════════════════════════════════════════════╗
║              حالة البرنامج                   ║
╠══════════════════════════════════════════════╣
║  وضع ~ (إضافة مسافات)    : {'🟢 مفعل' if SPACE_MODE else '🔴 معطل'}  ║
║  وضع التكرار             : {'🟢 مفعل' if REPEAT_MODE else '🔴 معطل'}  ║
║  الإرسال التلقائي        : {'🟢 مفعل' if AUTO_SEND else '🔴 معطل'}  ║
║  وضع الاستهداف           : {target_status}  ║
║  وضع التتبع              : {'🟢 مفعل' if TRACKING_MODE else '🔴 معطل'}  ║
║  المستخدم المتتبع        : {tracking_status}  ║
║  الرسائل المتبقية        : {len(available_messages)}  ║
╚══════════════════════════════════════════════╝
"""

def reset_messages_list():
    global available_messages, sent_messages
    available_messages = messages.copy()
    sent_messages = []
    random.shuffle(available_messages)
    print(f"📋 تم تجهيز {len(available_messages)} رسالة عشوائياً")

def get_next_random_message():
    global available_messages, sent_messages
    
    if not available_messages:
        print("🔄 نفذت الرسائل، إعادة تعيين القائمة...")
        reset_messages_list()
        if not available_messages:
            return None
    
    message = available_messages.pop(0)
    sent_messages.append(message)
    
    print(f"📊 تقدم الإرسال: {len(sent_messages)}/{len(messages)}")
    return message

async def auto_send_loop(client, chat_id):
    global AUTO_SEND, TARGET_MODE, TARGET_MESSAGE, TARGET_MSG_ID
    
    print("🔄 بدء الإرسال التلقائي...")
    
    if TARGET_MODE and TARGET_MESSAGE:
        print(f"🎯 وضع الاستهداف مفعل (الرد على رسالة محددة)")
    
    reset_messages_list()
    
    while AUTO_SEND:
        try:
            # ===== نظام الاستهداف فقط =====
            if TARGET_MODE and TARGET_MESSAGE:
                current_msg = get_next_random_message()
                if current_msg is None:
                    await asyncio.sleep(1)
                    continue
                
                await client.send_message(
                    chat_id,
                    current_msg,
                    reply_to=TARGET_MSG_ID
                )
                print(f"🎯 استهداف: {current_msg}")
            
            else:
                # إرسال عادي
                current_msg = get_next_random_message()
                if current_msg is None:
                    await asyncio.sleep(1)
                    continue
                
                await client.send_message(chat_id, current_msg)
                print(f"📤 تم إرسال: {current_msg}")
            
            print(f"📊 الرسائل المتبقية: {len(available_messages)}")
            
            if not available_messages:
                print("✨ جميع الرسائل تم إرسالها، سيتم إعادة تعيين القائمة...")
                await asyncio.sleep(2)
                reset_messages_list()
            
            await asyncio.sleep(SEND_DELAY)
        except Exception as e:
            print(f"❌ خطأ في الإرسال: {e}")
            await asyncio.sleep(5)

async def reply_to_message(client, chat_id, reply_to_msg_id, message):
    try:
        await client.send_message(
            chat_id,
            message,
            reply_to=reply_to_msg_id
        )
        return True
    except Exception as e:
        print(f"❌ خطأ في الرد: {e}")
        return False

def save_pid():
    try:
        with open(PID_FILE, 'w') as f:
            f.write(str(os.getpid()))
        print(f"📝 تم حفظ PID: {os.getpid()}")
    except Exception as e:
        print(f"⚠️ لم أتمكن من حفظ PID: {e}")

def remove_pid():
    try:
        if os.path.exists(PID_FILE):
            os.remove(PID_FILE)
            print("🗑️ تم حذف ملف PID")
    except Exception:
        pass

async def main():
    global SPACE_MODE, REPEAT_MODE, AUTO_SEND, send_task, available_messages, sent_messages
    global TARGET_MODE, TARGET_MESSAGE, TARGET_CHAT, TARGET_MSG_ID
    global TRACKING_MODE, TRACKING_USER, TRACKING_USER_ID, TRACKING_CHAT, TRACKING_USERNAME

    print("""
╔══════════════════════════════════════════════╗
║              Telegram Userbot                ║
╠══════════════════════════════════════════════╣
║  الأوامر:                                    ║
║  1  = تشغيل وضع ~                           ║
║  2  = إيقاف وضع ~                           ║
║  3  = تشغيل سكربت التكرار                   ║
║  4  = إيقاف سكربت التكرار                   ║
║  v70t = تشغيل الإرسال التلقائي العشوائي    ║
║  v00t = إيقاف الإرسال التلقائي              ║
║  v7استهداف0t = استهداف رسالة (ردود متكررة) ║
║  v7تتبع0t = تتبع مستخدم (رد على كل رسالته) ║
║  reset = إعادة تعيين قائمة الرسائل         ║
║  st = عرض الحالة                            ║
║  stop = إيقاف كل شيء                        ║
╚══════════════════════════════════════════════╝
""")

    save_pid()

    client = TelegramClient(SESSION_FILE, API_ID, API_HASH)

    print("[*] جاري الاتصال بـ Telegram...")

    await client.connect()

    if not await client.is_user_authorized():
        phone = input("📱 أدخل رقم الهاتف: ").strip()
        await client.send_code_request(phone)
        code = input("📨 أدخل كود Telegram: ").strip()
        try:
            await client.sign_in(phone=phone, code=code)
        except Exception as e:
            if "SessionPasswordNeeded" in type(e).__name__:
                password = input("🔐 أدخل كلمة مرور 2FA: ")
                await client.sign_in(password=password)
            else:
                raise

    me = await client.get_me()
    owner_id = me.id

    print()
    print("✅ تم تسجيل الدخول")
    print(f"👤 {me.first_name or ''} {me.last_name or ''}")
    print(f"🆔 {me.id}")
    print("-" * 50)
    print(get_status_text())

    @client.on(events.NewMessage())
    async def handler(event):
        global SPACE_MODE, REPEAT_MODE, AUTO_SEND, send_task, available_messages, sent_messages
        global TARGET_MODE, TARGET_MESSAGE, TARGET_CHAT, TARGET_MSG_ID
        global TRACKING_MODE, TRACKING_USER, TRACKING_USER_ID, TRACKING_CHAT, TRACKING_USERNAME

        try:
            if not event.raw_text:
                return
            text = event.raw_text.strip()
            if not text:
                return

            # ===== نظام التتبع: يرد على كل رسالة من المستخدم المتتبع =====
            # هذا يعمل بشكل مستقل عن الإرسال التلقائي
            if not event.out and TRACKING_MODE and TRACKING_USER_ID:
                # التأكد أن الرسالة من نفس الشات
                if event.chat_id == TRACKING_CHAT:
                    sender = await event.get_sender()
                    if sender:
                        # التحقق إذا كان المرسل هو المستخدم المتتبع
                        if sender.id == TRACKING_USER_ID:
                            # منع الرد على رسائل البوت نفسه
                            if sender.id == owner_id:
                                return
                            
                            # منع التكرار السريع
                            current_time = datetime.now().timestamp()
                            chat_key = f"track_{event.chat_id}_{TRACKING_USER_ID}"
                            
                            if chat_key in last_reply_time:
                                if current_time - last_reply_time[chat_key] < REPLY_COOLDOWN:
                                    return
                            
                            # الحصول على رسالة من القائمة
                            reply_msg = get_next_random_message()
                            if reply_msg:
                                # الرد على رسالة المستخدم
                                success = await reply_to_message(
                                    client,
                                    event.chat_id,
                                    event.id,
                                    reply_msg
                                )
                                if success:
                                    last_reply_time[chat_key] = current_time
                                    print(f"👁️ تتبع @{TRACKING_USERNAME}: {reply_msg}")
                                else:
                                    print(f"❌ فشل الرد على رسالة من {TRACKING_USERNAME}")

            # ===== معالجة الأوامر الصادرة =====
            if event.out:
                # ===== أمر الاستهداف (يرسل ردود متكررة على رسالة محددة) =====
                if text == "v7استهداف0t" or text == "v7target0t":
                    if event.is_reply:
                        reply_msg = await event.get_reply_message()
                        if reply_msg:
                            # حفظ معلومات الرسالة المستهدفة
                            TARGET_MODE = True
                            TARGET_MESSAGE = reply_msg
                            TARGET_CHAT = event.chat_id
                            TARGET_MSG_ID = reply_msg.id
                            
                            await delete_command_message(event)
                            
                            # إلغاء التتبع إذا كان مفعل
                            TRACKING_MODE = False
                            TRACKING_USER = None
                            TRACKING_USER_ID = None
                            TRACKING_CHAT = None
                            TRACKING_USERNAME = None
                            
                            # تفعيل الإرسال التلقائي إذا لم يكن مفعل
                            if not AUTO_SEND:
                                AUTO_SEND = True
                                send_task = asyncio.create_task(auto_send_loop(client, event.chat_id))
                            
                            print(f"🎯 تم تفعيل الاستهداف على الرسالة (ID: {TARGET_MSG_ID})")
                            return
                    else:
                        print("⚠️ الأمر v7استهداف0t يجب أن يكون رد على رسالة")
                    return

                # ===== أمر التتبع (يرد على كل رسالة من المستخدم) =====
                if text == "v7تتبع0t" or text == "v7track0t":
                    if event.is_reply:
                        reply_msg = await event.get_reply_message()
                        if reply_msg:
                            sender = await reply_msg.get_sender()
                            if sender:
                                # حفظ معلومات المستخدم المتتبع
                                TRACKING_USER_ID = sender.id
                                TRACKING_USER = sender
                                
                                # حفظ اسم المستخدم للعرض
                                if hasattr(sender, 'username') and sender.username:
                                    TRACKING_USERNAME = f"@{sender.username}"
                                elif hasattr(sender, 'first_name'):
                                    TRACKING_USERNAME = sender.first_name
                                else:
                                    TRACKING_USERNAME = str(sender.id)
                                
                                TRACKING_MODE = True
                                TRACKING_CHAT = event.chat_id
                                
                                await delete_command_message(event)
                                
                                # إلغاء الاستهداف إذا كان مفعل
                                TARGET_MODE = False
                                TARGET_MESSAGE = None
                                TARGET_MSG_ID = None
                                
                                # إيقاف الإرسال التلقائي إذا كان مفعل (لأن التتبع يعمل بشكل مستقل)
                                if AUTO_SEND:
                                    AUTO_SEND = False
                                    if send_task:
                                        send_task.cancel()
                                        try:
                                            await send_task
                                        except:
                                            pass
                                        send_task = None
                                
                                print(f"👁️ تم تفعيل التتبع للمستخدم: {TRACKING_USERNAME} (ID: {TRACKING_USER_ID})")
                                print(f"👁️ سيرد البوت على كل رسالة يرسلها {TRACKING_USERNAME}")
                                return
                    else:
                        print("⚠️ الأمر v7تتبع0t يجب أن يكون رد على رسالة المستخدم")
                    return

                if text == "1":
                    await delete_command_message(event)
                    SPACE_MODE = True
                    print("🟢 تم تشغيل وضع ~")
                    return

                if text == "2":
                    await delete_command_message(event)
                    SPACE_MODE = False
                    print("🔴 تم إيقاف وضع ~")
                    return

                if text == "3":
                    await delete_command_message(event)
                    REPEAT_MODE = True
                    print("🟢 تم تشغيل سكربت التكرار")
                    return

                if text == "4":
                    await delete_command_message(event)
                    REPEAT_MODE = False
                    print("🔴 تم إيقاف سكربت التكرار")
                    return

                if text.lower() == "v70t":
                    await delete_command_message(event)
                    # إلغاء الاستهداف والتتبع
                    TARGET_MODE = False
                    TARGET_MESSAGE = None
                    TARGET_MSG_ID = None
                    TRACKING_MODE = False
                    TRACKING_USER = None
                    TRACKING_USER_ID = None
                    TRACKING_CHAT = None
                    TRACKING_USERNAME = None
                    
                    if not AUTO_SEND:
                        AUTO_SEND = True
                        send_task = asyncio.create_task(auto_send_loop(client, event.chat_id))
                        print("🟢 تم تشغيل الإرسال التلقائي العشوائي")
                    else:
                        print("ℹ️ الإرسال التلقائي مفعل بالفعل")
                    return

                if text.lower() == "v00t":
                    await delete_command_message(event)
                    if AUTO_SEND:
                        AUTO_SEND = False
                        TARGET_MODE = False
                        TARGET_MESSAGE = None
                        TARGET_MSG_ID = None
                        if send_task:
                            send_task.cancel()
                            try:
                                await send_task
                            except:
                                pass
                            send_task = None
                        print("🔴 تم إيقاف الإرسال التلقائي")
                    else:
                        print("ℹ️ الإرسال التلقائي متوقف بالفعل")
                    
                    # إيقاف التتبع أيضاً
                    TRACKING_MODE = False
                    TRACKING_USER = None
                    TRACKING_USER_ID = None
                    TRACKING_CHAT = None
                    TRACKING_USERNAME = None
                    print("🔴 تم إيقاف التتبع")
                    return

                if text.lower() == "reset":
                    await delete_command_message(event)
                    reset_messages_list()
                    print("🔄 تم إعادة تعيين قائمة الرسائل")
                    return

                if text.lower() == "st":
                    await delete_command_message(event)
                    await client.send_message(event.chat_id, get_status_text())
                    return

                if text.lower() in STOP_COMMANDS:
                    await delete_command_message(event)
                    SPACE_MODE = False
                    REPEAT_MODE = False
                    TARGET_MODE = False
                    TARGET_MESSAGE = None
                    TARGET_MSG_ID = None
                    TRACKING_MODE = False
                    TRACKING_USER = None
                    TRACKING_USER_ID = None
                    TRACKING_CHAT = None
                    TRACKING_USERNAME = None
                    if AUTO_SEND:
                        AUTO_SEND = False
                        if send_task:
                            send_task.cancel()
                            try:
                                await send_task
                            except:
                                pass
                            send_task = None
                    print("⏹️ تم إيقاف كل شيء")
                    return

                if SPACE_MODE:
                    result = add_spaces(text)
                    if result != text:
                        try:
                            await event.delete()
                        except Exception:
                            pass
                        await client.send_message(event.chat_id, result)
                        print(f"⌨️ {text} ➡️ {result}")
                return

            # ===== نظام التكرار =====
            if not REPEAT_MODE:
                return

            if not is_repetition_message(text):
                return

            print(f"\n📨 رسالة واردة: {text}")
            result = process_repetition(text)
            if result != text:
                await client.send_message(event.chat_id, result)
                print(f"🤖 تم إرسال: {result}")

        except Exception as e:
            print(f"❌ خطأ: {e}")

    print()
    print("🤖 Userbot يعمل...")
    print()
    print("📌 الأوامر المتاحة:")
    print("   1  = تشغيل وضع ~")
    print("   2  = إيقاف وضع ~")
    print("   3  = تشغيل سكربت التكرار")
    print("   4  = إيقاف سكربت التكرار")
    print("   v70t = تشغيل الإرسال التلقائي العشوائي")
    print("   v00t = إيقاف الإرسال التلقائي")
    print("   v7استهداف0t = استهداف رسالة (ردود متكررة)")
    print("   v7تتبع0t = تتبع مستخدم (رد على كل رسالته)")
    print("   reset = إعادة تعيين قائمة الرسائل")
    print("   st = عرض الحالة")
    print("   stop = إيقاف كل شيء")
    print("-" * 50)

    try:
        await client.run_until_disconnected()
    finally:
        remove_pid()

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        print("\n⏹️ تم إيقاف البرنامج")
        remove_pid()
    except Exception as e:
        print(f"\n❌ خطأ: {e}")
        remove_pid()